import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    odd_numbers = list(filter(lambda x: x % 2 != 0, nums))
    for num in odd_numbers:
        print(num)

if __name__ == "__main__":
    main()
